import re
import math
from .i18n import gettext as _, ngettext, thousands_separator

__all__ = [
    "intcomma",
    "intword",
    "apnumber",
    "fractional",
    "scientific",
    "clamp",
    "metric",
    "powers",
    "human_powers",
]

# ---------- intcomma ----------

def intcomma(value, ndigits=None):
    """Converts an integer or float to a string containing commas every three digits.

    Args:
        value (int | float | str): Integer or float to convert.
        ndigits (int | None): Digits of precision for rounding after the decimal point.

    Returns:
        str: String containing commas every three digits.
    """
    sep = thousands_separator()
    try:
        if isinstance(value, str):
            float(value.replace(sep, ""))
        else:
            float(value)
    except (TypeError, ValueError):
        return value

    if ndigits is not None:
        orig = "{0:.{1}f}".format(value, ndigits)
    else:
        orig = str(value)

    new = re.sub(r"^(-?\d+)(\d{3})", fr"\g<1>{sep}\g<2>", orig)
    if orig == new:
        return new
    else:
        return intcomma(new)

# ---------- intword ----------

powers = [10 ** x for x in (3, 6, 9, 12, 15, 18, 21, 24, 27, 30, 33, 100)]
human_powers = (
    ("thousand", "thousand"),
    ("million", "million"),
    ("billion", "billion"),
    ("trillion", "trillion"),
    ("quadrillion", "quadrillion"),
    ("quintillion", "quintillion"),
    ("sextillion", "sextillion"),
    ("septillion", "septillion"),
    ("octillion", "octillion"),
    ("nonillion", "nonillion"),
    ("decillion", "decillion"),
    ("googol", "googol"),
)


def intword(value, format="%.1f"):
    """Converts a large integer to a friendly text representation.

    Works best for numbers over 1 million. For example, 1_000_000 becomes "1.0 million",
    1200000 becomes "1.2 million" and "1_200_000_000" becomes "1.2 billion". Supports up
    to decillion (33 digits) and googol (100 digits).
    """
    try:
        value = int(value)
    except (TypeError, ValueError):
        return value

    if value < powers[0]:
        return str(value)
    for ordinal, power in enumerate(powers[1:], 1):
        if value < power:
            chopped = value / float(powers[ordinal - 1])
            if float(format % chopped) == float(10 ** 3):
                chopped = value / float(powers[ordinal])
                singular, plural = human_powers[ordinal]
                return (" ".join([format, ngettext(singular, plural, math.ceil(chopped))])) % chopped
            else:
                singular, plural = human_powers[ordinal - 1]
                return (" ".join([format, ngettext(singular, plural, math.ceil(chopped))])) % chopped
    return str(value)

# ---------- apnumber ----------

def apnumber(value):
    """Converts an integer to Associated Press style."""
    try:
        value = int(value)
    except (TypeError, ValueError):
        return value
    if not 0 <= value < 10:
        return str(value)
    return (
        "zero",
        "one",
        "two",
        "three",
        "four",
        "five",
        "six",
        "seven",
        "eight",
        "nine",
    )[value]

# ---------- fractional ----------

def fractional(value):
    """Convert to fractional number."""
    if value is None:
        return None
    try:
        value = float(value)
    except (TypeError, ValueError):
        return value
    if value == 0:
        return "0"
    whole_number = int(math.floor(value))
    remainder = value - whole_number
    if remainder == 0:
        return str(whole_number)
    # Simplify fraction
    from fractions import Fraction
    frac = Fraction(remainder).limit_denominator(1000)
    numerator, denominator = frac.numerator, frac.denominator
    if whole_number == 0:
        return f"{numerator}/{denominator}"
    else:
        return f"{whole_number} {numerator}/{denominator}"

# ---------- scientific ----------

def scientific(value, precision=2):
    """Return number in string scientific notation z.wq x 10ⁿ.
    """
    exponents = {
        "0": "⁰",
        "1": "¹",
        "2": "²",
        "3": "³",
        "4": "⁴",
        "5": "⁵",
        "6": "⁶",
        "7": "⁷",
        "8": "⁸",
        "9": "⁹",
        "+": "⁺",
        "-": "⁻",
    }
    negative = False
    try:
        if isinstance(value, str) and "-" in value:
            value = value.replace("-", "")
            negative = True
        if isinstance(value, str):
            value = float(value)
        fmt = "{:.%se}" % str(int(precision))
        n = fmt.format(value)
    except (ValueError, TypeError):
        return value
    part1, part2 = n.split("e")
    if "-0" in part2:
        part2 = part2.replace("-0", "-")
    if "+0" in part2:
        part2 = part2.replace("+0", "")
    new_part2 = []
    if negative:
        new_part2.append(exponents["-"])
    for char in part2:
        new_part2.append(exponents[char])
    final_str = part1 + " x 10" + "".join(new_part2)
    return final_str

# ---------- clamp ----------

def clamp(value, fmt=None, min=None, max=None, under="<", over=">"):
    """Clamp a value to min/max thresholds.

    Args:
        value: The value to format.
        fmt: Either a format string (e.g. "{:.0%}") or a callable that returns a string.
        min: Minimum threshold.
        max: Maximum threshold.
        under: Prefix for values below min.
        over: Prefix for values above max.
    """
    if value is None:
        return None
    if fmt is None:
        formatted = str(value)
    elif callable(fmt):
        formatted = fmt(value)
    else:
        try:
            formatted = fmt.format(value)
        except Exception:
            formatted = str(value)
    try:
        numeric = float(value)
    except Exception:
        numeric = None
    if min is not None and numeric is not None and numeric < min:
        return f"{under}{formatted}"
    if max is not None and numeric is not None and numeric > max:
        return f"{over}{formatted}"
    return formatted

# ---------- metric ----------

def metric(value, precision=1):
    """Return a human readable string using SI unit prefixes.
    """
    try:
        num = float(value)
    except (TypeError, ValueError):
        return value
    if num == 0:
        return "0"
    sign = "-" if num < 0 else ""
    num = abs(num)
    prefixes = ["", "k", "M", "G", "T", "P", "E", "Z", "Y"]
    base = 1000.0
    exp = 0
    while num >= base and exp + 1 < len(prefixes):
        num /= base
        exp += 1
    formatted = f"{num:.{precision}f}"
    if '.' in formatted:
        formatted = formatted.rstrip('0').rstrip('.')
    return f"{sign}{formatted}{prefixes[exp]}"

